-- marc-fire-fighting-technology-lyttelton (researched)
UPDATE businesses SET description = 'Marcé Fire Fighting Technology has more than 20 years of experience in the supply, manufacture and maintenance of specialised fire fighting vehicles, including airport rescue fire fighting (ARFF) vehicles, mini, medium and major pumpers, water tankers, rapid intervention vehicles, grass fire units and 37-metre aerial platforms. The company produces up to 120 vehicles a year from its Centurion headquarters and a second manufacturing plant in Cape Town, and holds ISO 9001:2015 certification along with registration as a bodybuilder with the SABS and as a manufacturer, importer and bodybuilder with the Department of Transport.

Beyond South Africa, Marcé operates fully functional branches in Mozambique, Botswana, Namibia and Zimbabwe, plus an engineering office in Mauritius, while keeping around 98% of its vehicles locally manufactured. That combination of specialised vehicle manufacturing and an African branch network suits municipalities, airports and industrial sites across the region that need fire fighting vehicles built, serviced and supported close to where they operate.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.marce.co.za/about'), description_enriched_at = datetime('now') WHERE slug = 'marc-fire-fighting-technology-lyttelton' AND description = 'Marcé Fire Fighting Technology is a fire fighting vehicle manufacturer headquartered in Lyttelton Manor, Centurion, founded in 1997. It designs, builds and maintains fire fighting and airport rescue (ARFF) vehicles and offers turnkey fire station solutions from its 8,400 square metre Centurion manufacturing plant, producing up to 120 vehicles a year, and is ISO 9001:2015 certified.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
