-- mariammen-temple-marabastad (researched)
UPDATE businesses SET description = 'Mariammen Temple, built in 1905 in the Asiatic Bazaar area of Marabastad, is the oldest Hindu temple in Pretoria and is dedicated to Mariamman, the goddess followers of Hinduism believe watches over smallpox and other infectious diseases. Its ornate gopuram entrance on 6th Street is widely regarded as one of the most striking examples of its kind in South Africa, marking the temple out among Pretoria''s older religious buildings.

The temple serves as home to Pretoria''s Tamil League and was declared a national monument in 1982, recognising both its age and its continued role in the local Hindu and Tamil community. Mariammen Temple suits visitors interested in Pretoria''s religious and cultural history, offering a working place of worship that also stands as one of the city''s oldest surviving heritage buildings.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://en.wikipedia.org/wiki/Mariamman_Temple,_Pretoria'), description_enriched_at = datetime('now') WHERE slug = 'mariammen-temple-marabastad' AND description = 'Mariammen Temple is Pretoria''s oldest Hindu temple, built in 1905 in the Asiatic Bazaar area of Marabastad and dedicated to the goddess Mariamman. Its ornate gopuram entrance on 6th Street is considered one of the most impressive of its kind in South Africa, and the temple, home to Pretoria''s Tamil League, was declared a national monument in 1982.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
