-- burgers-park-pretoria-central (researched)
UPDATE businesses SET description = 'Burgers Park is a botanical garden in central Pretoria, founded in the 1870s and covering four acres, making it one of the city''s older public green spaces. It is named after Thomas François Burgers, the fourth president of the South African Republic, whose statue stands within the park grounds alongside a memorial to the South African Scottish Regiment from the Second World War.

Owned by the City of Tshwane Metropolitan Municipality and declared a South African National Monument, the park sits among a cluster of historic Pretoria landmarks that includes the nearby Pretoria City Hall and Palace of Justice. Burgers Park suits anyone looking for a quiet, historic garden in the middle of the city, combining botanical planting with the kind of monuments and memorials that give it a layered sense of Pretoria''s past.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://en.wikipedia.org/wiki/Burgers_Park'), description_enriched_at = datetime('now') WHERE slug = 'burgers-park-pretoria-central' AND description = 'Burgers Park is a botanical garden in central Pretoria, established in the 1870s and named after Thomas Francois Burgers, the fourth president of the South African Republic. It is a declared South African National Monument owned by the City of Tshwane, and features a statue of Burgers and a World War II memorial to the South African Scottish Regiment.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
